"""Tests for EPUB loading. Every EPUB here is generated by the test itself."""

from __future__ import annotations

import zipfile
from pathlib import Path

import pytest

pytest.importorskip("ebooklib")

from ebooklib import epub  # noqa: E402

from vocalpages.document import load_document  # noqa: E402
from vocalpages.epub_extract import (  # noqa: E402
    DrmProtectedError,
    EpubError,
    html_to_text,
    is_drm_protected,
)

CHAPTER_ONE = """<html><head><title>x</title><style>p { color: red; }</style></head><body>
<h1>The Beginning</h1>
<p>It was a quiet morning. Dr. Lee
   opened the door.</p>
<script>alert("never read me");</script>
<p>She said hello.<br/>Then she left.</p>
<span epub:type="pagebreak" id="p7">7</span>
</body></html>"""

CHAPTER_TWO = """<html><body>
<h2>Second Thoughts</h2>
<p>Pi is about 3.14 here. Wait... what?</p>
<ul><li>First item.</li><li>Second item.</li></ul>
</body></html>"""

IMAGE_ONLY = """<html><body><div><img src="cover.jpg" alt="Cover"/></div></body></html>"""

NO_HEADING = """<html><body><p>Final words without a heading.</p></body></html>"""


def make_epub(path: Path, *, title: str | None = "A Generated Book", author: str | None = "Test Author") -> Path:
    """Write a small EPUB whose spine order differs from file-name order."""
    book = epub.EpubBook()
    book.set_identifier("test-book-id")
    if title:
        book.set_title(title)
    book.set_language("en")
    if author:
        book.add_author(author)

    chapters = {
        "cover": epub.EpubHtml(title="Cover", file_name="a_cover.xhtml", content=IMAGE_ONLY),
        "one": epub.EpubHtml(title="One", file_name="z_one.xhtml", content=CHAPTER_ONE),
        "two": epub.EpubHtml(title="Two", file_name="b_two.xhtml", content=CHAPTER_TWO),
        "end": epub.EpubHtml(title="End", file_name="c_end.xhtml", content=NO_HEADING),
    }
    for chapter in chapters.values():
        book.add_item(chapter)
    book.toc = [chapters["one"], chapters["two"], chapters["end"]]
    book.add_item(epub.EpubNcx())
    book.add_item(epub.EpubNav())
    book.spine = ["nav", chapters["cover"], chapters["one"], chapters["two"], chapters["end"]]
    epub.write_epub(str(path), book)
    return path


def add_encryption(path: Path, algorithm: str) -> None:
    """Append a META-INF/encryption.xml that 'encrypts' a chapter with ``algorithm``."""
    xml = f"""<?xml version="1.0"?>
<encryption xmlns="urn:oasis:names:tc:opendocument:xmlns:container"
            xmlns:enc="http://www.w3.org/2001/04/xmlenc#">
  <enc:EncryptedData>
    <enc:EncryptionMethod Algorithm="{algorithm}"/>
    <enc:CipherData><enc:CipherReference URI="EPUB/z_one.xhtml"/></enc:CipherData>
  </enc:EncryptedData>
</encryption>"""
    with zipfile.ZipFile(path, "a") as archive:
        archive.writestr("META-INF/encryption.xml", xml)


@pytest.fixture
def sample_epub(tmp_path: Path) -> Path:
    return make_epub(tmp_path / "book.epub")


def test_chapters_follow_spine_order_and_skip_nav_and_images(sample_epub: Path) -> None:
    doc = load_document(sample_epub)
    assert doc.format == "epub"
    assert doc.unit == "Chapter"
    assert [s.title for s in doc.sections] == ["The Beginning", "Second Thoughts", "Chapter 3"]
    assert [s.number for s in doc.sections] == [1, 2, 3]


def test_metadata_title_and_author(sample_epub: Path) -> None:
    doc = load_document(sample_epub)
    assert (doc.title, doc.author) == ("A Generated Book", "Test Author")


def test_title_falls_back_to_filename(tmp_path: Path) -> None:
    doc = load_document(make_epub(tmp_path / "untitled-book.epub", title=None, author=None))
    assert doc.title == "untitled-book"
    assert doc.author == ""


def test_html_is_cleaned_to_readable_text(sample_epub: Path) -> None:
    first = load_document(sample_epub).section(1)
    assert "alert" not in first.text
    assert "color: red" not in first.text
    assert "7" not in first.text  # page-break marker removed
    assert first.sentences == (
        "The Beginning",
        "It was a quiet morning.",
        "Dr. Lee opened the door.",
        "She said hello.",
        "Then she left.",
    )


def test_list_items_and_tricky_punctuation(sample_epub: Path) -> None:
    second = load_document(sample_epub).section(2)
    assert second.sentences == (
        "Second Thoughts",
        "Pi is about 3.14 here.",
        "Wait... what?",
        "First item.",
        "Second item.",
    )


def test_html_to_text_returns_heading_and_paragraphs() -> None:
    heading, text = html_to_text("<body><h2>Title</h2><p>One.</p><div>Two\n three.</div></body>")
    assert heading == "Title"
    assert text == "Title\n\nOne.\n\nTwo three."


def test_drm_protected_epub_is_rejected(sample_epub: Path) -> None:
    add_encryption(sample_epub, "http://www.w3.org/2001/04/xmlenc#aes128-cbc")
    assert is_drm_protected(sample_epub)
    with pytest.raises(DrmProtectedError, match="DRM"):
        load_document(sample_epub)


def test_font_obfuscation_is_not_drm(sample_epub: Path) -> None:
    add_encryption(sample_epub, "http://www.idpf.org/2008/embedding")
    assert not is_drm_protected(sample_epub)
    assert load_document(sample_epub).section_count == 3


def test_corrupt_epub_raises(tmp_path: Path) -> None:
    bad = tmp_path / "bad.epub"
    bad.write_text("not a zip")
    with pytest.raises(EpubError):
        load_document(bad)


def test_epub_without_text_raises(tmp_path: Path) -> None:
    book = epub.EpubBook()
    book.set_identifier("empty")
    book.set_title("Empty")
    page = epub.EpubHtml(title="Pic", file_name="pic.xhtml", content=IMAGE_ONLY)
    book.add_item(page)
    book.add_item(epub.EpubNav())
    book.spine = [page]
    path = tmp_path / "empty.epub"
    epub.write_epub(str(path), book)
    with pytest.raises(EpubError, match="no readable text"):
        load_document(path)
